import java.io.*;
import java.nio.*;

public class Main {
    static final int CAP = 1 << 25;          // at most 2^25 letters fit in the input budget
    static final int MASK = (1 << 25) - 1;   // low 25 bits: radius (at most 2^24)

    public static void main(String[] args) throws IOException {
        // The JVM heap is capped at 60% of the memory limit, too small for 4 bytes per letter, so one
        // off-heap int per position packs the letter (high bits) with its Manacher radius (low bits).
        IntBuffer a = ByteBuffer.allocateDirect(CAP * 4).order(ByteOrder.nativeOrder()).asIntBuffer();
        byte[] buf = new byte[1 << 16];
        int n = 0;
        read:
        for (int len; (len = System.in.read(buf)) > 0;) {
            for (int j = 0; j < len; j++) {
                int c = buf[j];
                if (c == '\n') break read;
                if (c >= 'a' && c <= 'z') a.put(n++, (c - 'a') << 25);
            }
        }
        long answer = 0;
        // Odd centers: radius k counts the k palindromes s[i-t..i+t], t < k.
        for (int i = 0, l = 0, r = -1; i < n; i++) {
            int k = i > r ? 1 : Math.min(a.get(l + r - i) & MASK, r - i + 1);
            while (i - k >= 0 && i + k < n && (a.get(i - k) >>> 25) == (a.get(i + k) >>> 25)) k++;
            a.put(i, (a.get(i) & ~MASK) | k);
            answer += k;
            if (i + k - 1 > r) { l = i - k + 1; r = i + k - 1; }
        }
        // Even centers (between i-1 and i), reusing the same radius bits.
        for (int i = 0, l = 0, r = -1; i < n; i++) {
            int k = i > r ? 0 : Math.min(a.get(l + r - i + 1) & MASK, r - i + 1);
            while (i - k - 1 >= 0 && i + k < n && (a.get(i - k - 1) >>> 25) == (a.get(i + k) >>> 25)) k++;
            a.put(i, (a.get(i) & ~MASK) | k);
            answer += k;
            if (i + k - 1 > r) { l = i - k; r = i + k - 1; }
        }
        System.out.println(answer);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	reader := bufio.NewReaderSize(os.Stdin, 1<<16)
	// Up to 2^25 letters fit in the input budget; untouched capacity stays unmapped.
	s := make([]byte, 0, 1<<25)
	for {
		c, err := reader.ReadByte()
		if err != nil || c == '\n' {
			break
		}
		if c >= 'a' && c <= 'z' {
			s = append(s, c)
		}
	}
	n := len(s)
	radius := make([]int32, n)
	var answer int64
	// Odd centers: radius k counts the k palindromes s[i-t..i+t], t < k.
	for i, l, r := 0, 0, -1; i < n; i++ {
		k := 1
		if i <= r {
			k = min(int(radius[l+r-i]), r-i+1)
		}
		for i-k >= 0 && i+k < n && s[i-k] == s[i+k] {
			k++
		}
		radius[i] = int32(k)
		answer += int64(k)
		if i+k-1 > r {
			l, r = i-k+1, i+k-1
		}
	}
	// Even centers (between i-1 and i), reusing the same array.
	for i, l, r := 0, 0, -1; i < n; i++ {
		k := 0
		if i <= r {
			k = min(int(radius[l+r-i+1]), r-i+1)
		}
		for i-k-1 >= 0 && i+k < n && s[i-k-1] == s[i+k] {
			k++
		}
		radius[i] = int32(k)
		answer += int64(k)
		if i+k-1 > r {
			l, r = i-k, i+k-1
		}
	}
	fmt.Println(answer)
}
